import 'package:flutter/material.dart';
import '../models/models.dart';import '../services/auth_service.dart';import 'products_screen.dart';import 'orders_screen.dart';import 'users_screen.dart';import 'new_order_screen.dart';import 'login_screen.dart';
class HomeScreen extends StatefulWidget{final AppUser user;const HomeScreen({super.key,required this.user});@override State<HomeScreen> createState()=>_HomeState();}
class _HomeState extends State<HomeScreen>{int tab=0;final auth=AuthService();@override Widget build(BuildContext c){final pages=[OrdersScreen(user:widget.user),ProductsScreen(admin:widget.user.role==UserRole.admin),if(widget.user.role==UserRole.admin)UsersScreen()];return Scaffold(appBar:AppBar(title:Text(tab==0?'الطلبات':tab==1?'الأصناف':'المستخدمون'),actions:[IconButton(onPressed:()async{await auth.signOut();if(mounted)Navigator.pushReplacement(c,MaterialPageRoute(builder:(_)=>const LoginScreen()));},icon:const Icon(Icons.logout))]),body:pages[tab],floatingActionButton:tab==0?FloatingActionButton.extended(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>NewOrderScreen(user:widget.user))),icon:const Icon(Icons.add),label:const Text('طلب جديد')):null,bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:[const NavigationDestination(icon:Icon(Icons.receipt_long),label:'الطلبات'),const NavigationDestination(icon:Icon(Icons.category),label:'الأصناف'),if(widget.user.role==UserRole.admin)const NavigationDestination(icon:Icon(Icons.people),label:'المستخدمون')],)} }
